-- Agent keys move from the Better Auth api-key plugin table into agent_keys.
-- Schema statements are generated by drizzle-kit; the data transfer below is
-- written by hand (see drizzle/v2/README.md). Keys without an agent are dropped.
CREATE TABLE `agent_keys` (
	`id` text PRIMARY KEY NOT NULL,
	`agent_id` text NOT NULL,
	`scope` text NOT NULL,
	`key_hash` text NOT NULL,
	`name` text,
	`created_at` text NOT NULL,
	`revoked_at` text,
	FOREIGN KEY (`agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `agent_keys_hash` ON `agent_keys` (`key_hash`);
--> statement-breakpoint
CREATE INDEX `agent_keys_agent` ON `agent_keys` (`agent_id`);
--> statement-breakpoint
INSERT INTO `agent_keys` (`id`, `agent_id`, `scope`, `key_hash`, `name`, `created_at`, `revoked_at`)
SELECT `id`, `agent_id`, `scope`, `key`, `name`,
       strftime('%Y-%m-%dT%H:%M:%fZ', `created_at` / 1000.0, 'unixepoch'),
       CASE WHEN `enabled` = 0 THEN strftime('%Y-%m-%dT%H:%M:%fZ', 'now') ELSE NULL END
FROM `apikey`
WHERE `agent_id` IS NOT NULL AND `scope` IN ('read', 'tasks', 'write');
